// Raporun nereye gideceğini belirler; dört tetikleyici de buradan geçer:
//  • GET /webhook/hafta     → yanıt olarak döner (JSON),
//  • workflow 05'ten /hafta → isteyen sohbete gider,
//  • Pazar 20:00 / Elle Test Et → Telegram kuruluysa oraya, değilse mail.
const j = $input.first().json || {};
let kaynak = 'zaman';
if (Object.prototype.hasOwnProperty.call(j, 'query') || Object.prototype.hasOwnProperty.call(j, 'headers')) kaynak = 'webhook';
else if (j.chat_id) kaynak = 'bot';
return [{ json: { kaynak, chat_id: j.chat_id ? String(j.chat_id) : '' } }];

// Son 7 günün özeti + önümüzdeki 7 gün. Diğer workflow'ların dosyalarını
// YALNIZCA okur, hiçbir şey yazmaz. Bu yüzden bozuk dosyada durmaz:
// o bölüm "okunamadı" diye yazılır, rapor yine gider. Dosyası olmayan bölüm
// (o özelliği kurmadıysanız) sessizce atlanır.
const kaynak = $('Kaynağı Belirle').first().json;
const oku = (ad, alan) => {
  const okuHata = $(ad + ' Oku (Rapor)').first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return { yok: true, liste: [], veri: {} };
  const cik = $(ad + ' Çıkar (Rapor)').first().json || {};
  if (okuHata || cik.error) {
    return { bozuk: okuMesaj || String(cik.error.message || cik.error), liste: [], veri: {} };
  }
  const veri = cik.data || cik;
  return { liste: Array.isArray(veri[alan]) ? veri[alan].filter(Boolean) : [], veri };
};
const G = oku('Görevleri', 'gorevler');
const H = oku('Harcamaları', 'harcamalar');
const B = oku('Bütçeyi', 'kategoriler');
const A = oku('Alışkanlıkları', 'aliskanliklar');
const N = oku('Notları', 'notlar');
const S = oku('Abonelikleri', 'abonelikler');
const T = oku('Tarihleri', 'tarihler');
const V = oku('Servisleri', 'servisler');

const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 0 }) + ' TL';
const iki = (n) => String(n).padStart(2, '0');
const anahtar = (d) => d.getFullYear() + '-' + iki(d.getMonth() + 1) + '-' + iki(d.getDate());
const zaman = (s) => { const t = new Date(s).getTime(); return Number.isFinite(t) ? t : NaN; };
const GUN = 86400000;
const simdi = Date.now();
const bugun = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; })();
const haftaBas = simdi - 7 * GUN;
const oncekiBas = simdi - 14 * GUN;
const kisaTarih = (d) => d.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
const gunAdi = (d) => d.toLocaleDateString('tr-TR', { weekday: 'short', day: 'numeric', month: 'short' });

const bolumler = [];
const bolum = (baslik, satirlar) => bolumler.push({ baslik, satirlar });
const bozukBolum = (baslik, dosya, x) => { if (x.bozuk) { bolum(baslik, ['⚠️ ' + dosya + ' okunamadı: ' + x.bozuk]); return true; } return false; };

// ── ✅ Görevler ──────────────────────────────────────────────────────────────
if (!G.yok && !bozukBolum('✅ Görevler', 'gorevler.json', G)) {
  const biten = G.liste.filter((g) => g.durum === 'tamam' && zaman(g.tamamlanma) >= haftaBas);
  const eklenen = G.liste.filter((g) => zaman(g.olusturulma) >= haftaBas);
  const acik = G.liste.filter((g) => g.durum !== 'tamam');
  const s = [biten.length + ' tamamlandı · ' + eklenen.length + ' eklendi · ' + acik.length + ' açık'];
  biten.slice(0, 5).forEach((g) => s.push('✓ ' + g.baslik));
  if (biten.length > 5) s.push('… ve ' + (biten.length - 5) + ' tane daha');
  bolum('✅ Görevler', s);
}

// ── 💸 Harcama + 🎯 Bütçe ────────────────────────────────────────────────────
const harcamalar = H.liste.filter((h) => typeof h.tutar === 'number' && (!h.paraBirimi || h.paraBirimi === 'TL'));
if (!H.yok && !bozukBolum('💸 Harcama', 'harcamalar.json', H)) {
  const bu = harcamalar.filter((h) => zaman(h.tarih) >= haftaBas && zaman(h.tarih) <= simdi);
  const onceki = harcamalar.filter((h) => zaman(h.tarih) >= oncekiBas && zaman(h.tarih) < haftaBas);
  const toplam = bu.reduce((t, h) => t + h.tutar, 0);
  const oncekiToplam = onceki.reduce((t, h) => t + h.tutar, 0);
  if (bu.length === 0) {
    bolum('💸 Harcama', ['Bu hafta harcama kaydı yok.']);
  } else {
    let degisim = '';
    if (oncekiToplam > 0) {
      const y = Math.round(((toplam - oncekiToplam) / oncekiToplam) * 100);
      degisim = ' (geçen hafta ' + tl(oncekiToplam) + ', ' + (y > 0 ? '▲ %' + y : y < 0 ? '▼ %' + -y : 'aynı') + ')';
    }
    const s = [tl(toplam) + ', ' + bu.length + ' kayıt' + degisim];
    [...bu].sort((a, b) => b.tutar - a.tutar).slice(0, 3)
      .forEach((h) => s.push('• ' + tl(h.tutar) + ' — ' + String(h.konu || h.kimden || 'açıklama yok').slice(0, 50)));
    bolum('💸 Harcama', s);
  }
}
if (!B.yok && !bozukBolum('🎯 Bütçe', 'butce.json', B) && !H.bozuk) {
  const limit = typeof B.veri.aylikLimit === 'number' && B.veri.aylikLimit > 0 ? B.veri.aylikLimit : null;
  if (limit) {
    const ay = anahtar(bugun).slice(0, 7);
    const ayToplam = harcamalar.filter((h) => { const t = new Date(h.tarih); return !isNaN(t) && anahtar(t).slice(0, 7) === ay; })
      .reduce((t, h) => t + h.tutar, 0);
    const oran = Math.round((ayToplam / limit) * 100);
    const ayGun = new Date(bugun.getFullYear(), bugun.getMonth() + 1, 0).getDate();
    bolum('🎯 Bütçe', [(oran >= 100 ? '🔴 ' : oran >= 80 ? '🟠 ' : '') + 'Bu ay %' + oran + ' — ' + tl(ayToplam) + ' / ' + tl(limit) +
      ' (ayın ' + bugun.getDate() + '/' + ayGun + '. günü)']);
  }
}

// ── 🔥 Alışkanlık ────────────────────────────────────────────────────────────
if (!A.yok && !bozukBolum('🔥 Alışkanlık', 'aliskanliklar.json', A) && A.liste.length) {
  const son7 = [];
  for (let i = 6; i >= 0; i--) { const d = new Date(bugun); d.setDate(d.getDate() - i); son7.push(anahtar(d)); }
  const s = A.liste.filter((a) => a.ad).map((a) => {
    const set = new Set(Array.isArray(a.gunler) ? a.gunler : []);
    const kac = son7.filter((g) => set.has(g)).length;
    const d = new Date(bugun);
    if (!set.has(anahtar(d))) d.setDate(d.getDate() - 1);
    let seri = 0;
    while (set.has(anahtar(d))) { seri++; d.setDate(d.getDate() - 1); }
    return (kac === 7 ? '🏆 ' : '• ') + a.ad + ': ' + kac + '/7' + (seri > 0 ? ' · 🔥' + seri : '');
  });
  bolum('🔥 Alışkanlık', s);
}

// ── 📅 Önümüzdeki 7 gün ──────────────────────────────────────────────────────
const yaklasan = []; // { t: zaman, metin }
const pencereSonu = bugun.getTime() + 8 * GUN; // bugün + 7 gün (gün sonuna kadar)
N.liste.forEach((n) => {
  const t = zaman(n.hatirlat);
  if (n.durum !== 'gonderildi' && t > simdi && t < pencereSonu) yaklasan.push({ t, metin: '⏰ ' + n.metin });
});
const yillikGun = (yil, ay, gun) => new Date(yil, ay - 1, Math.min(gun, new Date(yil, ay, 0).getDate()));
S.liste.filter((a) => a.ad && a.aktif !== false).forEach((a) => {
  const gun = Math.min(31, Math.max(1, Number(a.gun) || 1));
  let d;
  if (a.periyot === 'yillik') {
    d = yillikGun(bugun.getFullYear(), Number(a.ay) || 1, gun);
    if (d < bugun) d = yillikGun(bugun.getFullYear() + 1, Number(a.ay) || 1, gun);
  } else {
    d = yillikGun(bugun.getFullYear(), bugun.getMonth() + 1, gun);
    if (d < bugun) d = yillikGun(bugun.getFullYear(), bugun.getMonth() + 2, gun);
  }
  if (d.getTime() < pencereSonu) {
    yaklasan.push({ t: d.getTime(), metin: '💳 ' + a.ad + (typeof a.tutar === 'number' ? ' — ' + tl(a.tutar) : '') });
  }
});
T.liste.filter((x) => x.ad).forEach((x) => {
  const m = String(x.tarih || '').match(/^(\d{4}|-)-(\d{2})-(\d{2})$/);
  if (!m) return;
  let d = yillikGun(bugun.getFullYear(), Number(m[2]), Number(m[3]));
  if (d < bugun) d = yillikGun(bugun.getFullYear() + 1, Number(m[2]), Number(m[3]));
  if (d.getTime() >= pencereSonu) return;
  const emoji = x.tur === 'dogumgunu' ? '🎂 ' : x.tur === 'yildonumu' ? '💍 ' : '📅 ';
  const k = m[1] !== '-' ? d.getFullYear() - Number(m[1]) : 0;
  yaklasan.push({ t: d.getTime(), metin: emoji + x.ad + (k > 0 ? (x.tur === 'dogumgunu' ? ' (' + k + ' yaş)' : ' (' + k + '. yıl)') : '') });
});
const uyari7 = [[N, 'notlar.json'], [S, 'abonelikler.json'], [T, 'tarihler.json']]
  .filter(([x]) => x.bozuk).map(([x, d]) => '⚠️ ' + d + ' okunamadı: ' + x.bozuk);
if (yaklasan.length || uyari7.length) {
  bolum('📅 Önümüzdeki 7 gün', [
    ...yaklasan.sort((a, b) => a.t - b.t).slice(0, 12).map((y) => gunAdi(new Date(y.t)) + ' · ' + y.metin),
    ...uyari7,
  ]);
}

// ── 🩺 Servisler (yalnızca kapalı olan varsa) ────────────────────────────────
if (!V.yok && !bozukBolum('🩺 Servisler', 'servisler.json', V)) {
  const kapali = V.liste.filter((s) => s.sonDurum === 'kapali');
  if (kapali.length) bolum('🩺 Servisler', kapali.map((s) => '🔴 ' + (s.ad || s.url) + ' — ' + (s.sonHata || 'kapalı')));
}

const bas = new Date(simdi - 6 * GUN);
const baslik = '📊 Haftalık rapor — ' + kisaTarih(bas) + ' – ' + kisaTarih(new Date(simdi));
const text = bolumler.length
  ? baslik + '\n\n' + bolumler.map((b) => b.baslik + '\n' + b.satirlar.join('\n')).join('\n\n')
  : baslik + '\n\nRaporlanacak veri yok. Görev, harcama ya da alışkanlık ekledikçe burası dolacak.';
const html = '<h2>' + esc(baslik) + '</h2>' + bolumler.map((b) =>
  '<h3>' + esc(b.baslik) + '</h3><ul>' + b.satirlar.map((s) => '<li>' + esc(s) + '</li>').join('') + '</ul>').join('');

return [{ json: { ...kaynak, text, konu: baslik, html, bolumler } }];

// GET /webhook/hafta ile istendiyse rapor yanıt olarak döner.
const j = $input.first().json;
return j.kaynak === 'webhook' ? [{ json: j }] : [];

// /hafta ile istendiyse isteyen sohbete; zamanlanmış çalışmada Telegram
// kuruluysa TELEGRAM_CHAT_ID'ye gider. Hiçbiri yoksa bu dal boş döner.
const j = $input.first().json;
if (j.kaynak === 'webhook') return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = j.kaynak === 'bot' ? j.chat_id : String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Zamanlanmış rapor, Telegram kurulu DEĞİLSE mail olarak gider.
const j = $input.first().json;
if (j.kaynak !== 'zaman') return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];
